import json

# Test input
test_input = [
    [8, 8, 6],
    [6, 3, 6],
    [6, 8, 8]
]

# Apply transformation
def input_to_blocks(grid):
    rows = len(grid)
    cols = len(grid[0])

    blocks = [[[] for _ in range(3)] for _ in range(3)]

    for bi in range(3):
        for bj in range(3):
            if bi == 1 and bj == 1:
                blocks[bi][bj] = [row[:] for row in grid]
            elif (bi == 0 and bj in [0, 2]) or (bi == 2 and bj in [0, 2]):
                rotated = grid[::-1]
                blocks[bi][bj] = [row[::-1] for row in rotated]
            elif bi == 0 or bi == 2:
                blocks[bi][bj] = grid[::-1]
            elif bj == 0 or bj == 2:
                blocks[bi][bj] = [row[::-1] for row in grid]

    output = []
    for bi in range(3):
        for ri in range(3):
            row = []
            for bj in range(3):
                for ci in range(3):
                    row.append(blocks[bi][bj][ri][ci])
            output.append(row)

    return output

